parameters.jsCode:
const items = $input.all();
const merged = {};
const countries = [];
const errors = [];
for (const item of items) {
  const raw = item.json;
  const stdout = String(raw.stdout || '');
  const stderr = String(raw.stderr || raw.error?.message || '');
  const metaLine = stdout.split(/\r?\n/).find((l) => l.startsWith('__DS_TOKEN_META__'));
  if (!metaLine) {
    errors.push({ country: '', error: { code: 'NO_META', message: stderr || 'no __DS_TOKEN_META__ in output' } });
    continue;
  }
  let meta;
  try {
    meta = JSON.parse(metaLine.replace('__DS_TOKEN_META__', ''));
  } catch (e) {
    errors.push({ country: '', error: { code: 'BAD_META', message: String(e && e.message) } });
    continue;
  }
  if (meta.success) {
    Object.assign(merged, meta.map || {});
    countries.push({ country: meta.countryCode, count: Object.keys(meta.map || {}).length });
  } else {
    errors.push({ country: meta.countryCode, error: meta.error });
  }
}
return [{ json: { success: true, map: merged, countries, errors, total: Object.keys(merged).length } }];
